import SwiftUI

/// The one object every screen reads. The Shell area owns creating the `Node` (see android CoreService.kt) and
/// sets `node` once the vault is unlocked. Other areas only read it; they never create or close it.
/// `Node` etc. are the UniFFI types in ios/build/generated/p2pcore.swift (regenerated by ios/scripts/build_core.sh).
@MainActor
final class AppEnv: ObservableObject {
    @Published var node: Node?
}
